// Ported from the Node app's Sequelize model StudentBoardRegistration (first generated by tools/gen-efcore.mjs).
using Microsoft.EntityFrameworkCore;
using Microsoft.EntityFrameworkCore.Metadata.Builders;
using SchoolERP.Domain.Entities;

namespace SchoolERP.Infrastructure.Persistence.Configurations;

internal sealed class StudentBoardRegistrationConfiguration : IEntityTypeConfiguration<StudentBoardRegistration>
{
    public void Configure(EntityTypeBuilder<StudentBoardRegistration> builder)
    {
        builder.ToTable("student_board_registrations", t =>
        {
            t.HasCheckConstraint("CK_student_board_registrations_status", "[status] IN (N'pending', N'submitted', N'registered')");
        });
        builder.ConfigureAudit();
        builder.HasQueryFilter(e => !e.Delstatus);
        builder.HasKey(e => e.Id);
        builder.Property(e => e.Id).HasColumnName("id").UseIdentityColumn();
        builder.Property(e => e.StudentId).HasColumnName("student_id");
        builder.Property(e => e.BoardId).HasColumnName("board_id");
        builder.Property(e => e.RegistrationNo).HasColumnName("registration_no").HasColumnType("nvarchar(40)").HasMaxLength(40);
        builder.Property(e => e.RollNo).HasColumnName("roll_no").HasColumnType("nvarchar(40)").HasMaxLength(40);
        builder.Property(e => e.ExamYear).HasColumnName("exam_year");
        builder.Property(e => e.Status).HasColumnName("status").HasColumnType("nvarchar(20)").IsRequired().HasDefaultValueSql("N'pending'");
        builder.HasIndex(e => new { e.StudentId, e.BoardId }).IsUnique().HasDatabaseName("uq_student_board_reg");
        builder.HasOne(e => e.Student).WithMany(p => p.StudentBoardRegistrations).HasForeignKey(e => e.StudentId).OnDelete(DeleteBehavior.NoAction);
    }
}
